/** @jsxImportSource kerfjs */
import { delegate } from 'kerfjs';
import { DialogHeader } from '@kerfjs/ui/dialog-header';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import { ValueTable } from '@kerfjs/ui/value-table';
import { EmptyState } from '@kerfjs/ui/empty-state';
import '@kerfjs/ui/layout.css';
import '@kerfjs/ui/sidebar.css';
import '@kerfjs/ui/webawesome.css';
import '@awesome.me/webawesome/dist/components/dialog/dialog.js';
import '@awesome.me/webawesome/dist/components/button/button.js';
import './master-detail-dialog.css';

type RecordItem = { id: string; name: string; owner: string; status: string; updated: string };
interface DialogElement extends HTMLElement { open: boolean; }
export function createMasterDetailDialog(
  id: string,
  records: RecordItem[],
  dispatch: (action: 'record.open' | 'record.copy-link', recordId: string) => void,
) {
  let selected = records[0]?.id;
  let open = false;
  let invoker: HTMLElement | null = null;
  const titleId = id + '-title';
  const summaryId = id + '-summary';
  const detail = () => records.find(record => record.id === selected);
  const render = () => {
    const record = detail();
    return <section class="record-browser kui-layout">
      <wa-button data-action="records.show">Browse project details</wa-button>
      <wa-dialog id={id} class="record-dialog" open={open} without-header
        label="Project details" aria-labelledby={titleId} aria-describedby={summaryId}>
        <DialogHeader title="Project details" titleId={titleId}
          summary="Choose a project to review its current delivery status." summaryId={summaryId}
          actions={<wa-button appearance="plain" data-action="records.close" aria-label="Close project details">Close</wa-button>} />
        <div class="record-dialog-body kui-dialog-body">
          <nav class="record-master kui-sidebar" aria-label="Project selection">
            <section class="kui-sidebar-section">
              <MenuHeader label="Projects" />
              {records.map(item => <MenuItem action="records.select" itemId={item.id} label={item.name} pressed={selected === item.id} multiline />)}
            </section>
          </nav>
          <section class="record-detail kui-section-stack" aria-label="Selected project details" aria-live="polite">
            {record ? <>
              <h3>{record.name}</h3>
              <ValueTable label="Read-only project metadata">
                <div><dt>Owner</dt><dd>{record.owner}</dd></div>
                <div><dt>Status</dt><dd>{record.status}</dd></div>
                <div><dt>Updated</dt><dd>{record.updated}</dd></div>
              </ValueTable>
              <div class="kui-control-cluster">
                <wa-button appearance="outlined" data-action="record.copy-link">Copy link</wa-button>
                <wa-button variant="brand" appearance="accent" data-action="record.open">Open project</wa-button>
              </div>
            </> : <EmptyState title="No projects" detail="There are no projects available to inspect." />}
          </section>
        </div>
      </wa-dialog>
    </section>;
  };
  function connect(root: HTMLElement, invalidate: () => void) {
    const getDialog = () => root.querySelector<DialogElement>('#' + CSS.escape(id));
    const actions = delegate(root, 'click', '[data-action]', (_event, element) => {
      const action = element.getAttribute('data-action');
      if (action === 'records.show') {
        invoker = element as HTMLElement;
        invoker.focus();
        open = true;
        const dialog = getDialog();
        if (dialog) dialog.open = true;
      } else if (action === 'records.close') {
        const dialog = getDialog();
        if (dialog) dialog.open = false;
      } else if (action === 'records.select') {
        const next = element.getAttribute('data-item-id');
        if (records.some(record => record.id === next)) { selected = next!; invalidate(); }
      } else if ((action === 'record.open' || action === 'record.copy-link') && selected) {
        dispatch(action, selected);
        if (action === 'record.open') { const dialog = getDialog(); if (dialog) dialog.open = false; }
      }
    });
    const afterHide = (event: Event) => {
      if (event.target !== getDialog()) return;
      open = false;
      invalidate();
      if (invoker?.isConnected) invoker.focus();
      else root.querySelector<HTMLElement>('[data-action="records.show"]')?.focus();
    };
    root.addEventListener('wa-after-hide', afterHide);
    return () => { actions(); root.removeEventListener('wa-after-hide', afterHide); };
  }
  return { render, connect };
}

