.record-browser { min-width:0; color:var(--kui-color-text); }
.record-dialog { --spacing:0; --width:min(62rem, calc(100vw - 2 * var(--kui-layout-dialog-inset))); }
.record-dialog-body { display:grid; grid-template-columns:minmax(0,.8fr) minmax(0,1.4fr); gap:var(--kui-layout-section-gap); }
.record-master { min-width:0; border-inline-end:1px solid var(--kui-color-border); }
.record-detail { min-width:0; overflow-wrap:anywhere; }
.record-detail h3 { margin:0; font-size:var(--kui-font-l); }
/* wa-dialog owns the single modal body scroll region. Neither column scrolls.
   DialogHeader stays outside the one dialog-body inset; sidebar owns its gutter. */
@media(max-width:48rem) {
  .record-dialog-body { grid-template-columns:minmax(0,1fr); }
  .record-master { border-inline-end:0; border-block-end:1px solid var(--kui-color-border); padding-block-end:var(--kui-layout-section-gap); }
}
